CREATE TABLE log(t TEXT); CREATE TABLE t1(x PRIMARY KEY, y, z UNIQUE); CREATE INDEX t1y ON t1(y); INSERT INTO t1 VALUES(1, 'i', 'eight'); INSERT INTO t1 VALUES(2, 'xii', 'twelve'); INSERT INTO t1 VALUES(3, 'v', 'thirty'); INSERT INTO t1 VALUES(4, 'iv', 'four'); CREATE TABLE t2(a,b); CREATE TABLE t3(k,v); INSERT INTO t2 VALUES(2,12),(3,5); INSERT INTO t3 VALUES(5,'v'),(12,'xii'); CREATE TRIGGER tr1 BEFORE UPDATE ON t1 BEGIN INSERT INTO log VALUES(old.z || '->' || new.z); END; CREATE TRIGGER tr2 AFTER UPDATE ON t1 BEGIN INSERT INTO log VALUES(old.y || '->' || new.y); END;